import {isNonPlayer} from './player-configuration.js';
import {updateRegionalTradeForm,readRegionalTradeChoice} from './regional-trade-ui.js';
import {eventTradeRegions} from './event-effects.js';
import {renderEventEffects} from './event-effects-ui.js';
import {AREAS} from './world.js';
import {tradeCapacity,EXPORT_PRICE,IMPORT_PRICE} from './trade.js';
import {COMMERCE,TRADE_LIMITS} from './commerce.js';
import {RESOURCE_LABELS} from './economy.js';
import {renderClientTradeForm,updateClientTradeForm,renderPrimaryTradeChoice} from './client-trade-ui.js';
import {usesGameLayout} from './client-platform.js';
const names={US:'美国',CN:'中国',EU:'欧盟',RU:'俄罗斯'};
function setup(){return `<section id="commerce-setup" class="flow-panel"><b>首次启用贸易记录</b><p>旧存档没有记录贸易卡的正反面。请按当前桌面勾选各方仍可用的贸易卡；取消勾选表示已用。此步骤不消耗行动。</p>${Object.entries(COMMERCE).map(([id,c])=>`<fieldset><legend>${names[id]}</legend>${Array.from({length:c.count},(_,i)=>`<label><input type="checkbox" data-commerce-ready="${id}" data-index="${i}" checked> 第${i+1}张可用</label>`).join('')}</fieldset>`).join('')}<button data-card-action="initializeCommerce">保存贸易卡状态</button></section>`;}
function renderExports(s,card,cap){const p=s.players[s.current];return `<fieldset><legend>出口 · 填0表示不卖</legend>${[0,1,2,3,4,6].map(k=>card.regionalInfluence?`<fieldset><legend>${RESOURCE_LABELS[k]} · 库存${p.resources[k]} · 单价${EXPORT_PRICE[k]}</legend>${Object.entries(AREAS).map(([region,area])=>{const n=cap.byRegion[region].exports[k];return `<label data-export-region-row ${n?'':'hidden'}>${area.name}（需求<span data-regional-cap="${region}:${k}">${n}</span>）<input type="number" data-export-region="${region}" data-export-region-key="${k}" min="0" max="${Math.min(n,p.resources[k])}" value="0" step="1"></label>`;}).join('')}</fieldset>`:`<label>${RESOURCE_LABELS[k]}（库存${p.resources[k]}，需求<span data-export-cap="${k}">${cap.exports[k]}</span>，单价${EXPORT_PRICE[k]}）<input type="number" data-export-key="${k}" min="0" max="${Math.min(p.resources[k],cap.exports[k])}" value="0" step="1"></label>`).join('')}</fieldset>`;}
export function renderTradeForm(s,id,card){if(!s.tradeVersion)return setup();if(usesGameLayout())return renderClientTradeForm(s,id,card);const p=s.players[s.current],cap=tradeCapacity(s,s.current,card,[],card.doublePrimary?0:undefined),limits=TRADE_LIMITS[s.current],bonus=card.regionalInfluence;
 const bonusNote=bonus?`请按目的地区填写出口数量；同一资源分给多个地区仍算一次出口。${(bonus.regions||Object.keys(AREAS)).map(id=>AREAS[id].name).join('、')}各自满足${bonus.minimumRevenue?'出口收入至少'+bonus.minimumRevenue+'资金（不扣进口支出，不含其他奖励）':Object.entries(bonus.requirements||{}).map(([k,n])=>'至少'+n+RESOURCE_LABELS[k]).join('和')}的出口要求后，在该地区添加1影响力。`:'';
 return `<section id="basic-form" data-card-id="${id}" class="flow-panel"><b>${card.name} · 自动贸易</b>${renderPrimaryTradeChoice(card)}<p>${card.maxTradeTypes?'本段合计只能交易'+card.maxTradeTypes+'种资源，进口或出口任选。':''}${card.tradeOnlyRegions?'本段仅使用'+card.tradeOnlyRegions.map(id=>AREAS[id].name).join('、')+'的盟国和展示国家。':card.virtualRegions?.length?'本段额外使用'+card.virtualRegions.map(id=>AREAS[id].name).join('、')+'展示国家的贸易符号。':''}最多出口${limits.exports}种、进口${limits.imports}种。每种资源只能交易一次，不能同时进出口。先结算出口，再按表中顺序进口。</p><p>${bonusNote}${card.doubleEnergy?'能源进出口符号均按双倍计算，其他资源不加倍。':''}</p><details><summary>查看本方贸易协定</summary><img class="viewerimage" src="assets/zh-CN/trade-${s.current}.webp" alt="${names[s.current]}贸易协定"></details>${s.config.wit&&!card.tradeOnlyRegions?`<fieldset><legend>SP扩展贸易 · 剩余${p.smart} SP</legend><p>每选一个地区消耗1 SP，使用当地展示国家的贸易符号，禁交国家除外。</p>${Object.entries(AREAS).filter(([r])=>!card.virtualRegions?.includes(r)&&!eventTradeRegions(s,s.current).includes(r)).map(([r,a])=>`<label><input type="checkbox" data-trade-region="${r}"> ${a.name}</label>`).join('')}</fieldset>`:''}${renderEventEffects(s,s.current,{textOnly:true})}${renderExports(s,card,cap)}<fieldset><legend>进口 · 填0表示不买</legend><p>向国家付款交给银行。${card.playersTrade===false?'':'向玩家付款转入对方资金；优先翻面其贸易卡，耗尽后才从其库存购买。'}</p>${[0,1,2,3,4].map(k=>`<fieldset><legend>${RESOURCE_LABELS[k]} · 单价${IMPORT_PRICE[k]}</legend><label>国家（最多<span data-import-cap="${k}">${cap.imports[k]}</span>）<input type="number" data-import-country="${k}" value="0" min="0" max="${cap.imports[k]}" step="1"></label>${card.playersTrade===false?'':Object.entries(COMMERCE).filter(([player,c])=>player!==s.current&&c.resources.includes(k)).map(([player,c])=>{const ready=s.players[player].commerce.filter(c=>c.ready).length,max=isNonPlayer(s,player)||ready?c.quantity:Math.min(c.quantity,s.players[player].resources[k]);return `<label>${names[player]}（最多${max}；可用贸易卡${ready}张）<input type="number" data-import-player="${player}" data-import-key="${k}" value="0" min="0" max="${max}" step="1"></label>`;}).join('')}</fieldset>`).join('')}</fieldset>${card.factory?'<label>贸易后生产消费品（0–2，照常消耗能源和原料）<input id="factory-goods" type="number" value="0" min="0" max="2" step="1"></label>':''}<p class="minor">${card.playersTrade===false?'':'向玩家进口至多奖励1外交。俄罗斯的单项进口不足3，不产生该奖励。'}${card.currencyBonus?'全球货币：每进口一种资源，贸易结束后获得5资金。':''}${card.doublePrimary?'能源巨擘：选择能源或原材料，只有所选资源的盟国进出口符号计算两次。':''}</p><p id="basic-preview" aria-live="polite"></p><button id="commit-basic" data-card-action="playBasicCard" data-id="${id}">结算全部交易并结束行动</button></section>`;
}
export function readTradeForm(){
 const primary=document.querySelector('[data-trade-primary]:checked');
 const exports=[...document.querySelectorAll('[data-export-key]')].filter(el=>Number(el.value)!==0).map(el=>({key:Number(el.dataset.exportKey),quantity:Number(el.value)})),regional=new Map();
 for(const el of document.querySelectorAll('[data-export-region-key]')){const n=Number(el.value);if(n===0)continue;const key=Number(el.dataset.exportRegionKey),row=regional.get(key)||{key,quantity:0,regions:{}};row.quantity+=n;row.regions[el.dataset.exportRegion]=n;regional.set(key,row);}exports.push(...regional.values());
 return {...readRegionalTradeChoice(),...(primary?{primaryResource:Number(primary.value)}:{}),tradeRegions:[...document.querySelectorAll('[data-trade-region]:checked')].map(el=>el.dataset.tradeRegion),exports,imports:[...document.querySelectorAll('[data-import-country]')].map(el=>{const key=Number(el.dataset.importCountry);return {key,countryQuantity:Number(el.value),players:Object.fromEntries([...document.querySelectorAll(`[data-import-key="${key}"]`)].map(input=>[input.dataset.importPlayer,Number(input.value)]))};}).filter(row=>row.countryQuantity!==0||Object.values(row.players).some(n=>n!==0)),factoryGoods:Number(document.querySelector('#factory-goods')?.value||0)};
}
export function readCommerceSetup(){return {type:'initializeCommerce',ready:Object.fromEntries(Object.keys(COMMERCE).map(id=>[id,[...document.querySelectorAll(`[data-commerce-ready="${id}"]`)].map(el=>el.checked)]))};}
export function tradeSummary(s,r){return `${s.players[s.current].money}资金 → ${r.players[s.current].money}资金\n外交 ${r.diplomacy?'√':'×'}${r.factoryGoods?'；生产'+r.factoryGoods+'消费品':''}${r.bonusRegions?.length?'；'+r.bonusRegions.map(id=>AREAS[id].name).join('、')+'影响力 +1':''}`;}
export function renderCommerce(s){if(!s.tradeVersion)return '';const p=s.players[s.current],cfg=COMMERCE[s.current];return `<details class="economy-tracks"><summary>贸易卡 · ${p.commerce.filter(c=>c.ready).length}/${cfg.count}可用</summary><p>每张提供${cfg.resources.map(k=>cfg.quantity+' '+RESOURCE_LABELS[k]).join(' 或 ')}，共用正反面。生产其中一种资源即可恢复本方全部贸易卡。</p>${p.commerce.map((c,i)=>`<button data-commerce-index="${i}">${i+1} · ${c.ready?'可用':'已用'} · 手动翻面</button>`).join('')}<p class="minor">手动翻面仅用于尚未自动处理的卡牌或事件效果。</p></details>`;}

export function updateTradeForm(s,card){if(!document.querySelector('[data-export-key], [data-export-region-key]'))return;const action=readTradeForm(),cap=tradeCapacity(s,s.current,card,action.tradeRegions,action.primaryResource),p=s.players[s.current];
 for(const el of document.querySelectorAll('[data-export-key]')){const k=Number(el.dataset.exportKey);el.max=Math.min(p.resources[k],cap.exports[k]);document.querySelector(`[data-export-cap="${k}"]`).textContent=cap.exports[k];}
 for(const el of document.querySelectorAll('[data-export-region-key]')){const k=Number(el.dataset.exportRegionKey),region=el.dataset.exportRegion,n=cap.byRegion[region].exports[k];el.max=Math.min(p.resources[k],n);el.closest('[data-export-region-row]').hidden=n===0&&Number(el.value)===0;document.querySelector(`[data-regional-cap="${region}:${k}"]`).textContent=n;}
 for(const el of document.querySelectorAll('[data-import-country]')){const k=Number(el.dataset.importCountry);el.max=cap.imports[k];document.querySelector(`[data-import-cap="${k}"]`).textContent=cap.imports[k];}
 for(const el of document.querySelectorAll('.client-trade-form [data-export-cap]'))el.textContent=cap.exports[Number(el.dataset.exportCap)];
 updateClientTradeForm();updateRegionalTradeForm(s,card,action,cap);
}
